({cara = 'neutra', piel: pielDada, pelo = '#2b1d14', peinado, ropa = '#33566e', pantalon = '#2c3442', zapato = '#2a2118', ojo = '#4a2f1c', mujer = false, barba = false, gafas = false, edad = 0, bata = false, habla = 0, mira = 0, pasos = 0, brazoI = 0, brazoD = 0, abierto, children}) => {
const {s} = useS();
const piel = pielDada || tonoDe([ropa, pelo, peinado, mujer, barba].join('|'));
const p = Math.sin(s * 8) * 26 * pasos;
