const pl = edad > 0.5 ? '#c9c6c0' : pelo;
const pe = peinado ?? (mujer ? 'largo' : 'corto');
const tela = bata ? '#f2f3f1' : ropa;
const hombro = mujer ? 104 : 124, cint = mujer ? 74 : 92, cad = mujer ? 104 : 96;
const tronco = `M${-hombro} -690C${-hombro + 30} -726 -72 -738 -40 -750H40C72 -738 ${hombro - 30} -726 ${hombro} -690Q${hombro + 12} -630 ${cint} -520L${cad} -440H${-cad}L${-cint} -520Q${-hombro - 12} -630 ${-hombro} -690Z`;
const Brazo = (l: number, a: number) => (
<g transform={`rotate(${-l * (10 + a * 140)} ${l * (hombro - 8)} -702)`}>
<g fill="none" stroke={piel} strokeLinecap="round">
{[-18, -6, 6, 18].map((d, i) => <path key={i} d={`M${l * (hombro + 6 + d)} -430L${l * (hombro + 6 + d * 1.3)} ${-372 + Math.abs(d) * 0.7}`} strokeWidth={12} />)}
<path d={`M${l * (hombro - 12)} -448L${l * (hombro - 26)} -402`} strokeWidth={14} />
</g>
<Vol d={`M${l * (hombro + 28)} -476Q${l * (hombro + 34)} -440 ${l * (hombro + 28)} -420Q${l * (hombro + 6)} -408 ${l * (hombro - 16)} -420Q${l * (hombro - 20)} -440 ${l * (hombro - 16)} -476Z`} c={piel} />
<Vol d={`M${l * (hombro - 44)} -700Q${l * (hombro + 4)} -716 ${l * (hombro + 16)} -674L${l * (hombro + 32)} -470Q${l * (hombro + 6)} -458 ${l * (hombro - 20)} -470Z`} c={tela} />
</g>
);
const cabello = {
